```python
def parse_query(query: str) -> dict:
    """Parse a query string into a dictionary of parameters.
    
    Handles:
    - Multiple values for the same key (converted to list)
    - Empty values (e.g., 'a' becomes {'a': ''})
    - Values containing '=' (e.g., 'a=1=2' becomes {'a': '1=2'})
    """
    params = {}
    for param in query.split('&'):
        if '=' in param:
            key, value = param.split('=', 1)
        else:
            key, value = param, ''
        if key in params:
            if isinstance(params[key], list):
                params[key].append(value)
            else:
                params[key] = [params[key], value]
        else:
            params[key] = value
    return params
